package com.example.demo.controller;

import com.example.demo.dto.UserDTO;
import com.example.demo.service.UserService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/users")
@CrossOrigin(origins = "*")
public class UserWebController {

private final UserService userService;

    public UserWebController(UserService userService) {
        this.userService = userService;
    }

    @PostMapping
    public ResponseEntity<?> criar(@RequestBody UserDTO dto) {

        userService.createUser(dto);

        return ResponseEntity.ok("Usuário criado com sucesso");
    }

}

package com.example.demo.controller;

import com.example.demo.dto.UserDTO;
import com.example.demo.service.UserService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/users")
@CrossOrigin(origins = "*")
public class UserWebController {

private final UserService userService;

    public UserWebController(UserService userService) {
        this.userService = userService;
    }

    @PostMapping
    public ResponseEntity<?> criar(@RequestBody UserDTO dto) {

        userService.createUser(dto);

        return ResponseEntity.ok("Usuário criado com sucesso");
    }

    @GetMapping
    public ResponseEntity<?> listar() {
        // Assuming you have a method to get all users, but since it's not there, perhaps return a message
        return ResponseEntity.ok("Endpoint GET /users - implemente listagem se necessário");
    }
}

